-- Original project/build column names and uniqueness, with no customer data import.
CREATE TABLE api_cloud_projects(project_id text PRIMARY KEY,account_id text NOT NULL,repository_identity text NOT NULL,repository_url text NOT NULL,display_name text NOT NULL,default_branch text NOT NULL,visibility text NOT NULL CHECK(visibility IN ('public','private')),git_connection_kind text NOT NULL,cloud_environment jsonb NOT NULL DEFAULT '{}',secret_bindings jsonb NOT NULL DEFAULT '[]',configuration_digest text NOT NULL,state text NOT NULL CHECK(state IN ('connected','preparing','ready','failed')),included boolean NOT NULL DEFAULT true,last_error_code text,idempotency_key text NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,UNIQUE(account_id,repository_identity),UNIQUE(account_id,idempotency_key));
CREATE TABLE api_cloud_project_builds(build_id text PRIMARY KEY,project_id text,account_id text NOT NULL,provider text NOT NULL,provider_sandbox_id text,snapshot_id text,source_commit text,template_version text NOT NULL,configuration_digest text NOT NULL,settings jsonb NOT NULL DEFAULT '{}',log_text text,state text NOT NULL,last_error_code text,idempotency_key text NOT NULL,next_action_at bigint NOT NULL,revision bigint NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE api_cloud_snapshots(provider text,snapshot_id text,account_id text,state text,PRIMARY KEY(provider,snapshot_id));
